mkitem!{mkimpl!{impl < 'tcx > Pat < 'tcx > { pub fn simple_ident (& self) -> Option < Symbol > { match self . kind { PatKind :: Binding { name , mode : BindingMode (ByRef :: No , _) , subpattern : None , .. } => Some (name) , _ => None , } } # [doc = " Call `f` on every \"binding\" in a pattern, e.g., on `a` in"] # [doc = " `match foo() { Some(a) => (), None => () }`"] pub fn each_binding (& self , mut f : impl FnMut (Symbol , ByRef , Ty < 'tcx > , Span)) { self . walk_always (| p | { if let PatKind :: Binding { name , mode , ty , .. } = p . kind { f (name , mode . 0 , ty , p . span) ; } }) ; } # [doc = " Walk the pattern in left-to-right order."] # [doc = ""] # [doc = " If `it(pat)` returns `false`, the children are not visited."] pub fn walk (& self , mut it : impl FnMut (& Pat < 'tcx >) -> bool) { self . walk_ (& mut it) } fn walk_ (& self , it : & mut impl FnMut (& Pat < 'tcx >) -> bool) { if ! it (self) { return ; } for_each_immediate_subpat (self , | p | p . walk_ (it)) ; } # [doc = " Whether the pattern has a `PatKind::Error` nested within."] pub fn pat_error_reported (& self) -> Result < () , ErrorGuaranteed > { let mut error = None ; self . walk (| pat | { if let PatKind :: Error (e) = pat . kind && error . is_none () { error = Some (e) ; } error . is_none () }) ; match error { None => Ok (()) , Some (e) => Err (e) , } } # [doc = " Walk the pattern in left-to-right order."] # [doc = ""] # [doc = " If you always want to recurse, prefer this method over `walk`."] pub fn walk_always (& self , mut it : impl FnMut (& Pat < 'tcx >)) { self . walk (| p | { it (p) ; true }) } # [doc = " Whether this a never pattern."] pub fn is_never_pattern (& self) -> bool { let mut is_never_pattern = false ; self . walk (| pat | match & pat . kind { PatKind :: Never => { is_never_pattern = true ; false } PatKind :: Or { pats } => { is_never_pattern = pats . iter () . all (| p | p . is_never_pattern ()) ; false } _ => true , }) ; is_never_pattern } }}}
mkitem!{mkstruct!{# [derive (Clone , Debug , HashStable , TypeVisitable)] pub struct Ascription < 'tcx > { pub annotation : CanonicalUserTypeAnnotation < 'tcx > , # [doc = " Variance to use when relating the `user_ty` to the **type of the value being"] # [doc = " matched**. Typically, this is `Variance::Covariant`, since the value being matched must"] # [doc = " have a type that is some subtype of the ascribed type."] # [doc = ""] # [doc = " Note that this variance does not apply for any bindings within subpatterns. The type"] # [doc = " assigned to those bindings must be exactly equal to the `user_ty` given here."] # [doc = ""] # [doc = " The only place where this field is not `Covariant` is when matching constants, where"] # [doc = " we currently use `Contravariant` -- this is because the constant type just needs to"] # [doc = " be \"comparable\" to the type of the input value. So, for example:"] # [doc = ""] # [doc = " ```text"] # [doc = " match x { \"foo\" => .. }"] # [doc = " ```"] # [doc = ""] # [doc = " requires that `&'static str <: T_x`, where `T_x` is the type of `x`. Really, we should"] # [doc = " probably be checking for a `PartialEq` impl instead, but this preserves the behavior"] # [doc = " of the old type-check for now. See #57280 for details."] pub variance : ty :: Variance , }}}
mkitem!{mkenum!{# [derive (Clone , Debug , HashStable , TypeVisitable)] pub enum PatKind < 'tcx > { # [doc = " A missing pattern, e.g. for an anonymous param in a bare fn like `fn f(u32)`."] Missing , # [doc = " A wildcard pattern: `_`."] Wild , AscribeUserType { ascription : Ascription < 'tcx > , subpattern : Box < Pat < 'tcx > > , } , # [doc = " `x`, `ref x`, `x @ P`, etc."] Binding { name : Symbol , # [type_visitable (ignore)] mode : BindingMode , # [type_visitable (ignore)] var : LocalVarId , ty : Ty < 'tcx > , subpattern : Option < Box < Pat < 'tcx > > > , # [doc = " Is this the leftmost occurrence of the binding, i.e., is `var` the"] # [doc = " `HirId` of this pattern?"] # [doc = ""] # [doc = " (The same binding can occur multiple times in different branches of"] # [doc = " an or-pattern, but only one of them will be primary.)"] is_primary : bool , } , # [doc = " `Foo(...)` or `Foo{...}` or `Foo`, where `Foo` is a variant name from an ADT with"] # [doc = " multiple variants."] Variant { adt_def : AdtDef < 'tcx > , args : GenericArgsRef < 'tcx > , variant_index : VariantIdx , subpatterns : Vec < FieldPat < 'tcx > > , } , # [doc = " `(...)`, `Foo(...)`, `Foo{...}`, or `Foo`, where `Foo` is a variant name from an ADT with"] # [doc = " a single variant."] Leaf { subpatterns : Vec < FieldPat < 'tcx > > , } , # [doc = " `box P`, `&P`, `&mut P`, etc."] Deref { subpattern : Box < Pat < 'tcx > > , } , # [doc = " Deref pattern, written `box P` for now."] DerefPattern { subpattern : Box < Pat < 'tcx > > , # [doc = " Whether the pattern scrutinee needs to be borrowed in order to call `Deref::deref` or"] # [doc = " `DerefMut::deref_mut`, and if so, which. This is `ByRef::No` for deref patterns on"] # [doc = " boxes; they are lowered using a built-in deref rather than a method call, thus they"] # [doc = " don't borrow the scrutinee."] # [type_visitable (ignore)] borrow : ByRef , } , # [doc = " One of the following:"] # [doc = " * `&str`, which will be handled as a string pattern and thus"] # [doc = "   exhaustiveness checking will detect if you use the same string twice in different"] # [doc = "   patterns."] # [doc = " * integer, bool, char or float, which will be handled by"] # [doc = "   exhaustiveness to cover exactly its own value, similar to `&str`, but these values are"] # [doc = "   much simpler."] # [doc = " * raw pointers derived from integers, other raw pointers will have already resulted in an"] # [doc = " * `String`, if `string_deref_patterns` is enabled."] Constant { value : ty :: Value < 'tcx > , } , # [doc = " Pattern obtained by converting a constant (inline or named) to its pattern"] # [doc = " representation using `const_to_pat`. This is used for unsafety checking."] ExpandedConstant { # [doc = " [DefId] of the constant item."] def_id : DefId , # [doc = " The pattern that the constant lowered to."] # [doc = ""] # [doc = " HACK: we need to keep the `DefId` of inline constants around for unsafety checking;"] # [doc = " therefore when a range pattern contains inline constants, we re-wrap the range pattern"] # [doc = " with the `ExpandedConstant` nodes that correspond to the range endpoints. Hence"] # [doc = " `subpattern` may actually be a range pattern, and `def_id` be the constant for one of"] # [doc = " its endpoints."] subpattern : Box < Pat < 'tcx > > , } , Range (Arc < PatRange < 'tcx > >) , # [doc = " Matches against a slice, checking the length and extracting elements."] # [doc = " irrefutable when there is a slice pattern and both `prefix` and `suffix` are empty."] # [doc = " e.g., `&[ref xs @ ..]`."] Slice { prefix : Box < [Pat < 'tcx >] > , slice : Option < Box < Pat < 'tcx > > > , suffix : Box < [Pat < 'tcx >] > , } , # [doc = " Fixed match against an array; irrefutable."] Array { prefix : Box < [Pat < 'tcx >] > , slice : Option < Box < Pat < 'tcx > > > , suffix : Box < [Pat < 'tcx >] > , } , # [doc = " An or-pattern, e.g. `p | q`."] # [doc = " Invariant: `pats.len() >= 2`."] Or { pats : Box < [Pat < 'tcx >] > , } , # [doc = " A never pattern `!`."] Never , # [doc = " An error has been encountered during lowering. We probably shouldn't report more lints"] # [doc = " related to this pattern."] Error (ErrorGuaranteed) , }}}
mkitem!{mkstruct!{# [doc = " A range pattern."] # [doc = " The boundaries must be of the same type and that type must be numeric."] # [derive (Clone , Debug , PartialEq , HashStable , TypeVisitable)] pub struct PatRange < 'tcx > { # [doc = " Must not be `PosInfinity`."] pub lo : PatRangeBoundary < 'tcx > , # [doc = " Must not be `NegInfinity`."] pub hi : PatRangeBoundary < 'tcx > , # [type_visitable (ignore)] pub end : RangeEnd , pub ty : Ty < 'tcx > , }}}
mkitem!{mkimpl!{impl < 'tcx > PatRange < 'tcx > { # [doc = " Whether this range covers the full extent of possible values (best-effort, we ignore floats)."] # [inline] pub fn is_full_range (& self , tcx : TyCtxt < 'tcx >) -> Option < bool > { let (min , max , size , bias) = match * self . ty . kind () { ty :: Char => (0 , std :: char :: MAX as u128 , Size :: from_bits (32) , 0) , ty :: Int (ity) => { let size = Integer :: from_int_ty (& tcx , ity) . size () ; let max = size . truncate (u128 :: MAX) ; let bias = 1u128 << (size . bits () - 1) ; (0 , max , size , bias) } ty :: Uint (uty) => { let size = Integer :: from_uint_ty (& tcx , uty) . size () ; let max = size . unsigned_int_max () ; (0 , max , size , 0) } _ => return None , } ; let lo_is_min = match self . lo { PatRangeBoundary :: NegInfinity => true , PatRangeBoundary :: Finite (value) => { let lo = value . try_to_scalar_int () . unwrap () . to_bits (size) ^ bias ; lo <= min } PatRangeBoundary :: PosInfinity => false , } ; if lo_is_min { let hi_is_max = match self . hi { PatRangeBoundary :: NegInfinity => false , PatRangeBoundary :: Finite (value) => { let hi = value . try_to_scalar_int () . unwrap () . to_bits (size) ^ bias ; hi > max || hi == max && self . end == RangeEnd :: Included } PatRangeBoundary :: PosInfinity => true , } ; if hi_is_max { return Some (true) ; } } Some (false) } # [inline] pub fn contains (& self , value : ty :: Value < 'tcx > , tcx : TyCtxt < 'tcx >) -> Option < bool > { use Ordering :: * ; debug_assert_eq ! (value . ty , self . ty) ; let ty = self . ty ; let value = PatRangeBoundary :: Finite (value . valtree) ; Some (match self . lo . compare_with (value , ty , tcx) ? { Less | Equal => true , Greater => false , } && match value . compare_with (self . hi , ty , tcx) ? { Less => true , Equal => self . end == RangeEnd :: Included , Greater => false , } ,) } # [inline] pub fn overlaps (& self , other : & Self , tcx : TyCtxt < 'tcx >) -> Option < bool > { use Ordering :: * ; debug_assert_eq ! (self . ty , other . ty) ; Some (match other . lo . compare_with (self . hi , self . ty , tcx) ? { Less => true , Equal => self . end == RangeEnd :: Included , Greater => false , } && match self . lo . compare_with (other . hi , self . ty , tcx) ? { Less => true , Equal => other . end == RangeEnd :: Included , Greater => false , } ,) } }}}
mkitem!{mkimpl!{impl < 'tcx > fmt :: Display for PatRange < 'tcx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { if let & PatRangeBoundary :: Finite (valtree) = & self . lo { let value = ty :: Value { ty : self . ty , valtree } ; write ! (f , "{value}") ? ; } if let & PatRangeBoundary :: Finite (valtree) = & self . hi { write ! (f , "{}" , self . end) ? ; let value = ty :: Value { ty : self . ty , valtree } ; write ! (f , "{value}") ? ; } else { write ! (f , "..") ? ; } Ok (()) } }}}
